auth.query:
supabaseAdmin.auth.admin.createUser({
      email,
      password,
      email_confirm: true, // ← mark as confirmed immediately, skip all emails
      user_metadata: {
        display_name: username,
        username: username,
        full_name: username,
        avatar_url: "/avt-placeholder.jpg",
      },
    })

supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (session?.user) {
          setUser(mapSupabaseUser(session.user));
          // Clean up legacy token if Supabase session is active
          localStorage.removeItem("auth_token");
        } else {
          // Only clear user if there is no legacy token (to allow co-existence during testing)
          const legacyToken = localStorage.getItem("auth_token");
          if (!legacyToken) {
            setUser(null);
          }
        }
        setIsLoading(false);
      }
    )

realtime.query:
supabase
      .channel(`chat-room:${activeConversation.id}-${Math.random().toString(36).substring(7)}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "messages",
          filter: `conversation_id=eq.${activeConversation.id}`,
        },
        (payload) => {
          const newRow = payload.new as any;

          // Verify duplicate rows are ignored
          setMessages((prev) => {
            if (prev.some((m) => m.id === newRow.id)) return prev;

            const isCurrentUser = newRow.sender_id === user?.id;

            // Instantly sync active viewing states
            if (!isCurrentUser) {
              const isCurrentUserSeller = activeConversation.sellerId === user?.id;
              void supabase
                .from("conversations")
                .update({
                  [isCurrentUserSeller ? "unread_for_seller" : "unread_for_buyer"]: 0,
                })
                .eq("id", activeConversation.id);
            }

            const senderName = isCurrentUser 
              ? (user?.name || "Me") 
              : activeConversation.recipientName;
            const senderAvatar = isCurrentUser 
              ? (user?.picture || "/avt1.png") 
              : activeConversation.recipientAvatar;

            return [
              ...prev,
              {
                id: newRow.id,
                senderId: newRow.sender_id,
                text: newRow.text,
                createdAt: newRow.created_at,
                senderName,
                senderAvatar,
              },
            ];
          });
        }
      )
      .subscribe()

supabase
      .channel(`inbox-chats-${accountId}-${Math.random().toString(36).substring(7)}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "messages",
        },
        (payload) => {
          const newRow = payload.new as any;
          if (newRow && newRow.sender_id !== accountId) {
            const activeChatId = (window as any).difmarkActiveChatId;
            if (newRow.conversation_id !== activeChatId) {
              playNotificationSound();
            }
          }
          void fetchConversations();
        }
      )
      .subscribe()

